# -*- coding: utf-8 -*-
translations_1 = {
    "601923": "אספן מפעלים",
    "601925": "מילוי",
    "601926": "קוניאק",
    "601927": "אספן מפעלים",
    "601931": "בנק",
    "601932": "חברת ביטוח",
    "601933": "תעלות",
    "601948": "תשמע, נמאס לי לגמרי מהקפה פה לאחרונה. נדמה לי שייטב לי אם אכין אותו בעצמי, אה? היה חבר טוב והבא לי כמה מאותם פולים שהם מגדלים שם",
    "601949": "אה, הנה הם, נפלא, נפלא. תגיד, אין לך מושג איך קולים את הדברים הארורים האלה? לא? ובכן. הממ.",
    "601950": "משקיע מעוניין בכמה פולים כדי לנסות את כוחו בהכנת קפה בעצמו.",
    "601951": "צלי של יום ראשון",
    "601952": "אין לך עיניים בראש?",
    "601953": "לאחרונה, כמה מטיפוסי החברה הגבוהה שלך שאלו על העיצובים הגספרוביאניים שלי. הם אומרים שהם לא מבינים על מה כל המהומה! אני חושש שראייתם נחלשת; אנא תקן את קווי הראייה שלהם, ומהר!",
    "601954": "ארטור דורש שתשמור על מעמד המשקיעים שלך מצויד היטב במשקפיים, כדי שיוכלו להעריך טוב יותר את יצירותיו.",
    "601955": "עכשיו המשקיעים שלך לא מפסיקים לבחון כל חיבור ולוח בעיר שלי. הם כמעט גרועים כמו מפקחי בטיחות! אני מצטמרר מהמחשבה... אבל לפחות כיוונת אותם לנתיב היופי. אני אמור להיות אסיר תודה.",
    "601965": "סטנדרטים של יופי",
    "601968": "ארוחת מסתורין קסומה",
    "601969": "תראה את השטיחים האלה! איזו מלאכת מחשבת! אני כמעט מרגיש רע להשתמש בהם כקישוטים. הם יגמרו ספוגים בשעוות נרות ובדם מזויף כשהלילה ייגמר... אני בטוח אשלח לך הזמנה!",
    "601970": "אתה יודע, יכולתי לעשות זאת בעצמי. יכולתי! אבל אני אדם עסוק והעברת סחורות בין אנבסה לעולם הישן לוקחת נצח... אני מעדיף להקדיש את הזמן לכתיבת העלילה לארוחה. אתה חושב שמישהו יתנגד אם אכתוב את מר בלייק כרוזן ערפד?",
    "601971": "וילי רוצה לארגן ארוחת מסתורין של רצח, אך הוא זקוק לעזרה ברכישת הנרות המעוטרים והשטיחים הדרושים לעיצוב התפאורה.",
    "601972": "אני מארגן ארוחת מסתורין של רצח עבור החוג המאגי שלי. הנושא? רצח באקספרס למזרח! אבל המחסנים שלי מעבר לים קצת ריקים, ואני לא יכול להתקמצן על זה... קומץ של אנשים חשובים אחרים עשויים להופיע, אתה יודע. אני בטוח שתוכל להוכיח את עצמך בפניהם על ידי הושטת יד!",
    "601973": "היו לנו כאן הרבה יותר עצים לפני שהגעת. עכשיו הכל לבנים ומלט. בלי ירוק, בלי העצים הטרופיים שיצלו עלינו מהשמש, לאן נלך להירגע?",
    "601976": "האי הופך למכוער יותר! חורנלרו זה מעוניין שתשמור על הטבע על ידי שתילת לפחות 10 עצים טרופיים ברחבי העיר.",
    "601990": "ארוחת מסתורין קסומה: ליהוק שחקנים",
    "601991": "לגבי התוכניות שלי לארוחת המסתורין של הרצח: אני זקוק לשחקנים חדשים, כאלה שהחוג המאגי שלי עדיין לא מכיר. לכן החלטתי לגייס כמה באי שלך! אבל אני לא רוצה שיכורים. שמור על אספקת רום יציבה כדי שאוכל לראות למי מהם אין מספיק איפוק לעבודה הזו.",
    "601992": "וילי רוצה לגייס שחקנים למסיבת מסתורין הרצח שלו באי שלך ומחפש את הפיקחים ביותר מביניהם.",
    "601994": "מצאתי את ההתאמה המושלמת, למרות שכמה מהם עדיין הריחו מרום. או, אבל לא אספר לך יותר, ההזמנות כבר נכתבו ועומדות להישלח. אני לא רוצה לקלקל את ההנאה.",
    "601995": "ארוחת מסתורין קסומה: קמפיין פרסום",
    "601996": "אני חושב שעליך לפרסם את ארוחת המסתורין של הרצח שלי בעיתון שלך. אתגמל אותך בנדיבות!",
    "601997": "וילי מבקש ממך לעשות קצת פרסום למסיבת מסתורין הרצח שלו בעיתון שלך, כדי שסוחרים אחרים ירצו להצטרף.",
    "601998": "כל הכבוד, כל הכבוד. הנה ההזמנה שלך. עכשיו לך, אני חייב לגשת להכנות האחרונות!",
    "602008": "סניף דואר",
    "602018": "אספקת מזוודות",
    "602019": "הזמנה",
    "602020": "ארוחת מסתורין קסומה",
    "602022": "וילי יצר באורח קסם הזמנה בתוך בית המכס שלך. הבא אותה אל המגדלור שלו כדי להצטרף למסיבה.",
    "602024": "הזמנה לארוחת המסתורין של הרצח של וילי. היא מריחה כמו לבנדר וגופרית.",
    "602025": "ארוחה קסומה",
    "602026": "אל פחד! זו הבמה לאירוע החדש ביותר של וילי ויבלסוק: ארוחת מסתורין של רצח בלב ים. הפלגת הבכורה תהיה למוזמנים בלבד, אך בשבועות הבאים היא תיפתח גם לקהל הרחב. רכשו את הכרטיסים שלכם כעת כדי לסעוד, לפתור פשע וליהנות מזמן נפלא!",
    "602027": "[AssetData([NotificationContext CharacterGUID]) Text] מבקש ממך להביא את ההזמנה שלך למסיבה.",
    "602030": "ארוחת מסתורין קסומה",
    "602031": "חברים ועמיתים יקרים, ברוכים הבאים למסיבת ארוחת הערב הקסומה של וילי! אנא עלו לסיפון, אנו נפליג בקרוב. והודיעו למלצרים מיד אם אינכם רוצים דם מזויף על הבגדים היקרים שלכם.",
    "602032": "הצטרפת למסיבת מסתורין הרצח של וילי.",
    "602035": "המופע התחיל. בזמן שאתם סועדים אוכל משובח, השחקנים סביבכם מפיקים את המרב מטיוטת היד של וילי. במהלך המנה הראשונה דמות משנית \"נרצחת\" על ידי אדם עטוף שחורים, וכל האורחים שביש מזלם לשבת קרוב מדי אליו מרוססים בדם מזויף. איך תיהנה מהלילה הזה?",
    "602036": "אתה מנסה להבין מי הרוצח, כמובן!",
    "602037": "אתה משתכר - הדרך היחידה ליהנות מהבלגן הזה.",
    "602038": "יש לך כמה רעיונות יצירתיים לגבי איך לשפר את המחזה...",
    "602039": "וילי שמט את ההזמנה למסיבה שלו בנמל שלך.",
    "602040": "[AssetData([NotificationContext CharacterGUID]) Text] רוצה שתפרסם את מסיבת מסתורין הרצח שלו.",
    "602041": "סטנדרטים של יופי",
    "602043": "ככל שהערב מתקדם, אתה עוקב בקפידה אחר העלילה ומתשאל את הדמויות כמו בלש.<br />ההתלהבות שלך מדבקת ובמהרה רוב הנוכחים דרוכים במקומותיהם, מתווכחים על הרצח ונהנים ממשחק העמדת הפנים.<br />עם זאת, אתה מגלה מהר מאוד שתפנית העלילה שהסיפור נבנה לקראתה אינה טובה כפי שהייתה יכולה להיות. הרוצח חייב להיות דמות משנית משעממת שאף אחד לא שם לב אליה. אתה מרגיש שאתה יודע איך לסיים את הסיפור הזה בפיצוץ...",
    "602044": "אתה מחליט שעדיף לא לגנוב את אור הזרקורים של וילי.",
    "602045": "אתה מסכים בסתר עם השחקנים לשנות את הסוף.",
    "602046": "במחצית הדרך של המופע, אתה כבר כל כך שיכור שאתה לא יכול לדעת אם זו הספינה או הראש שלך שנעים למעלה ולמטה ולצדדים.<br />השחקנים עושים את המיטב שלהם, נשמות מסכנות, והם כנראה אפילו לא מקבלים מספיק תשלום! מתוך טוב לב טהור אתה קונה את כל השמפניה שנשארה על הסיפון ומביא אותה לחדר ההלבשה. עד שהרוצח אמור להיחשף, המסיבה כולה כבר הפכה להילולה.",
    "602047": "זה עלה לך, אבל כולם מלבד וילי נהנו מזמנם.",
    "602048": "סנפירים נוצצים",
    "602049": "היו שמועות על צפייה בבתולות ים. הדייגים רוצים לפייס את הימים במנחה ראויה, אך אינם יכולים להרשות זאת לעצמם.",
    "602050": "ראינו את זה! זנבות נוצצים ושירים יפים, אבל יש להן שיניים חדות, אני אומר לך. אנחנו צריכים לפייס אותן בפנינים כדי שיעזבו את סירות הדיג שלנו לנפשן.",
    "602053": "חמרמורת",
    "602054": "התנצלותי, זה היה לילה ארוך. ייתכן שעמיתיי עשו קצת בלגן. אני מאחר לפגישה, אז אכפת לך לנקות בזמן שאני הולך להרוויח עוד כסף?",
    "602055": "נראה שמסיבה יצאה מכלל שליטה. כדאי שתבדוק במועדון החברים אם יש אורחי מסיבה חריגים.",
    "602056": "מצא את חיית המשק שנמלטה בסביבת מועדון החברים.",
    "602057": "החזירים של המשקיע",
    "602058": "חברים במקומות מוזרים",
    "602060": "האמן מציע לך מתנה שקיבל במקור מחבר לעט שלו.",
    "602086": "נתיב נהר",
    "602087": "נתיב נהר",
    "602088": "מפעל נייר",
    "700154": "מעגן ציבורי או תיירותי",
    "802099": "<b>ספינת הקיטור שלך גולשת ללא מאמץ.</b> הצוות נשען מעל המעקות כדי להביט במושבת הסרגסום, השופעת יצור ימי כמו סרטנים ודגים טרופיים. האצות נפרדות בקלות לפני ספינתך. היעדר הרוח אינו מהווה קושי כפי שהיה מהווה עבור סירת מפרש, ואכן, כאשר אתה גורר אותם למים פתוחים, צוות הספינה שבמצוקה מסביר שלא האצות, אלא הדומיה היא שעיכבה אותם. הם שמחים להימצא, וכמה מהם מציעים להצטרף למשלחת שלך.",
    "802572": "<b>עקבותיהם מובילות ללגונה חופית.</b> שמש הבוקר מלטפת את הדיונות המובילות אל ומסביב לסגלגל הטורקיז המושלם, אל צוק קטן שממנו ניתן לראות תריסר או יותר לגונות כאלה. אין זכר לגנבים, אך השיחים כאן סבוכים מספיק כדי שיוכלו להסתתר בהם. <b>סביר להניח שהם פונים אל הגבעות השחורות שמעבר.</b>",
    "802576": "<b>הגנבים עברו בגבעות אלו רק לאחרונה.</b> פילוס דרך בין הלגונות, קריאת עקבות, ענפים שבורים וכל השאר, חבורת הציד שלך מבחינה לבסוף בשלישיית המזיקים המתרחקת המטפסת במעלה מדרון שומם לעבר חווה. \"תפסנו אותם!\" הם אומרים, אך בהגיעם לחווה המבודדת, לחוואי יש חדשות רעות. \"הם גנבו לי את הסוסים!\" <b>נראה שאין סיכוי לתפוס אותם ברגל.</b> \"אני מעריך את זה שניסיתם לתפוס את החוטאים האלה, אבל אני לא יכול לתת לעוד מהיפות האלה ללכת בחינם! אלא אם כן תרצו לנסות לאלף סוס פרא...\"",
    "802580": "<b>לסוסי הפרא יש מרץ ששווה לרתום!</b> למרות שהם זה עתה אולפו, עיניהם מטורפות, נחיריהם מורחבים, אחת מלוחשות הסוסים שלך גורמת להם במהרה לאכול מכף ידה. בטפיפה מהירה יש להם אנרגיה אינסופית, ו<b>היתרון של הגנבים נעלם תוך זמן קצר.</b> המנוולים מכותרים, מופשטים מנשקם, ומושארים לפגעי מזג האוויר. הכספים הגנובים מוחזרים לקופות, והמשלחת ממשיכה בשמחה פעם נוספת!",
    "803363": "המגפה הגדולה",
    "803364": "<b>נערה מקומית מתה מאבעבועות שחורות;</b> מחלה שהמשלחת שלך ללא ספק הביאה לחופים אלה. בזמן שאמה בוכה על גופה הרפוי והמכוסה בנקודות, זה נראה בלתי נמנע שההדבקה תגבה חיים נוספים. \"אולי נוכל לחסן?\" אומר הקפטן, \"לכל הפחות נוכל להמליץ על אמצעי זהירות כדי למנוע את התפשטות המחלה.\"",
    "803365": "תן לרופא הספינה לייצר חיסון",
    "803366": "<b>תוכנית חיסון כה מוכנה היטב תעלה...</b> הרופא המומחה שלך מתאים תכשיר יעיל בנסיבות העניין, תוך שימוש בכמות נכבדה מהציוד הרפואי של הספינה בתהליך. אחד הקצינים תוהה אם לא כדאי לקבל משהו בתמורה לכל הצדקה הזו...",
    "803368": "מכור למקומיים את החיסון שלך",
    "803369": "קבל את העסקה",
    "803370": "<b>למקומיים אין ברירה אלא לקבל</b>— כל דבר כדי למנוע את המגפה שרופאיך חזו בחומרה רבה כל כך. הצוות שלך מקבל ברצון את מנחותיהם מבלי לעצור ולחשוב על המוסר המפוקפק של חילופין כאלה. אחרי הכל, הם אלה שהביאו את המחלה למקום הזה!",
    "803371": "סרב לעסקה",
    "803372": "הצע חיסון בחינם",
    "803373": "<b>אתה מגייס רופא מבטיח!</b> ללא דיון רב, המקומיים מסכימים לקבל את החיסונים נגד אבעבועות שחורות, מה שככל הנראה מציל את חייהם. זהו אולי תוצר לוואי של הפתיחות והאלטרואיזם הברור שבהם רופאיך מבצעים את המשימה, שרופא מקומי מקבל השראה להצטרף למשלחת שלך.",
    "803374": "<b>הרופא חולה.</b> אתה יכול רק להניח שניסיון החיסון נכשל גם עבור המקומיים, מכיוון שבועיים לתוך המשך המסע, יוצר החיסון אחוז באבעבועות שחורות. ברגע שהמחלה מתפרצת אין לה תרופה, אלא אם כן תבחר לבטוח בחייו של הרופא המסכן בידי שמיים.",
    "803375": "אלוהים יעזור במקום שבו הרפואה נכשלת",
    "803376": "<b>כמה אמיצים משרתים כמלאכים שומרים,</b> מתפללים, רוחצים, ומנחמים את הרופא. הריח החריף של השלפוחיות, המאפיין כל כך אבעבועות שחורות, ממוסך במהרה בענני קטורת. לאחר מספר שבועות החום של הרופא יורד והפריחה פוחתת. למרות שזה אינו נס— העור ישא לנצח את הצלקות— המשמעות היא הישרדותו של הרופא.",
    "803377": "<b>האבעבועות השחורות מתפשטות בקנאות מסיונרית.</b> בעקבות הצעתו הטיפשית של הכומר שכל הצוות יבקר את הרופא כדי לשאת את תפילותיהם, זה כמעט לא מפתיע כאשר מדווחים על שורה של מקרים חדשים. שלושה שבועות לאחר מות הרופא, אחרים רק מתחילים לחוות את התסמינים המייסרים הראשונים. אילו היה הצוות שלך נוטש את הרופא ללא רחמים, זו בוודאי הייתה האפשרות הטובה יותר.",
    "803378": "נטוש את הרופא",
    "803379": "<b>בצער רב, יש להפקיר את הרופא.</b> אנשים בכפפות נושאים אלונקה במעלה החוף אל מעבר לקו הגאות למקום מוצל שבו נראה סביר שהרופא יחיה עוד מספר ימים. \"אוויר צח עשוי להחיות אותך,\" אומר אחד באופטימיות, אך לרופא כבר אין כוח להשיב.",
    "803380": "נסה למנוע התפשטות נוספת",
    "803381": "<b>ההוראות מבוצעות כלשונן.</b> המקומיים מעולם לא באו במגע עם אבעבועות שחורות לפני כן, אך מסכימים לאמץ את האמצעים שקבעת נגדה. גם לצוות שלך נדרשת תזכורת; כיסוי הפה בעת שיעול, הימנעות ממגע בעור, ושטיפה תכופה של הידיים בתמיסה אלכוהולית. זה מעציב שעצם נוכחותך גרמה למותה של אותה נערה מסכנה, אך לאחר שבועיים ללא מקרים נוספים, זו בהחלט הקלה שהיא לא נראית כמי שהתפשטה.",
    "803382": "<b>אנשיך מוצאים שזה בלתי אפשרי להעביר את המסר.</b> המקומיים ממשיכים בעסקיהם כרגיל, מתעלמים מההגבלות שניסית להחיל. בתחושת המגפה הקרבה, וככל שהחששות לבריאות הצוות שלך גוברים, ייתכן שהגיע הזמן פשוט לעזוב...",
    "803383": "ערוך ניסוי עם חיסון",
    "803384": "<b>ניצלתם על ידי פרה חולת אבעבועות הפרות.</b> רופאיך נזכרים שהמילה חיסון (Vaccination) מגיעה מהמילה הפרה (Vacca), ומפיקים אבעבועות פרות מהעטינים המוגלתיים של בהמה מקומית. כולם מקבלים את הזריקה, אותה הרופא אינו מסוגל לטהר בשל היעדר מתקנים מתאימים. למרבה המזל זה גורם רק למספר התפרצויות של זיהומים אחרים, הרבה פחות הרסניים.",
    "803385": "<b>הדברים מקבלים תפנית חמורה לרעה...</b> לרופאיך אין מושג מה הם עושים, והחלטתם החריגה להשתמש בדגימה מהשלפוחיות של הנערה המתה המסכנה כדי ליצור את החיסון שלהם רק מאיצה את ההתפשטות. בייאוש, אלה שעדיין בריאים מסכימים לעלות על ספינת המשלחת ולברוח כל עוד הם יכולים.",
    "803386": "עזוב מהר ככל שתוכל",
    "803387": "<b>אבעבועות שחורות מחקו תרבויות שלמות.</b> זו החרדה האופפת את המשלחת כשהיא מתכוננת לעזיבה מהירה. המקומיים נראים לא מודעים לסכנה, אולי חושבים שמותה של הנערה הוא מקרה בודד. לפני העזיבה, אחד מסופריך מתעד בעצב את המנהגים והמסורות של אנשים אלה למקרה שזה ישמש כעדות היחידה לכך שהם אי פעם היו קיימים.",
    "803388": "באפשרותך לבחור למכור את החיסון שלך למקומיים",
}
